// The shape of every block in the shared blocks pack that a game can repaint (Paintball), for the
// "#mod-blocks" import (modBlocksPlugin). The blocks pack is generated by the private block-pack
// project and git-ignored; its own block script carries a table of every block's kind and whether
// it's a full cube (packs/blocks/behavior_pack/scripts/data.js), which this reads at build time.
// Without the pack installed, the table is empty and games paint only vanilla blocks.
import { existsSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = fileURLToPath(new URL("../../", import.meta.url));
export const MOD_BLOCKS_DATA = join(root, "packs", "blocks", "behavior_pack", "scripts", "data.js");

/** A block's entry in the blocks pack's table: its kind, and 1 when it's a full solid cube. */
export interface ModBlockEntry {
  k: string;
  f?: number;
}

/** Kinds a game can repaint in a shape of its own, by the table's kind (connected-texture panes are panes). */
const SHAPES: Record<string, string> = {
  stairs: "stairs",
  slab: "slab",
  vertical_slab: "vertical_slab",
  wall: "wall",
  pane: "pane",
  ct_pane: "pane",
  fence: "fence",
  gate: "gate",
  door: "door",
  trapdoor: "trapdoor",
};

/** Each repaintable block's shape: "cube" for a full cube of any kind, else its shape; other blocks are left out. */
export function modBlockShapes(blocks: Readonly<Record<string, ModBlockEntry>>): Record<string, string> {
  const shapes: Record<string, string> = {};
  for (const [id, entry] of Object.entries(blocks)) {
    const shape = entry.f ? "cube" : SHAPES[entry.k];
    if (shape) shapes[id] = shape;
  }
  return shapes;
}

/** The installed blocks pack's shapes, or {} when it isn't installed. */
export async function readModBlockShapes(file = MOD_BLOCKS_DATA): Promise<Record<string, string>> {
  if (!existsSync(file)) return {};
  const data = (await import(pathToFileURL(file).href)) as { BLOCKS?: Record<string, ModBlockEntry> };
  return modBlockShapes(data.BLOCKS ?? {});
}
